/* 本美化免费发布于🍠抹茶，不准倒卖二传等一切商业化行为！ */
/* 二改作者：冬雪 */
/* 部分代码参考源@旅程美化教程贴的老师们 */
/* 素材来源忧郁涵/ 土豆烤肉*/
/*基于抹茶的代码上二改，已获得代码授权二改发布*/


/* UI背景图 只显示一张原图、不重复、不拉伸、居中完整显示 */
.drawer-content {
    background-image: url('https://img.51shazhu.com/autoupload/Se-4Rw5dFaWDOM3CV9c4D9iO_OyvX7mIgxFBfDMDErs/20260419/tUhK/1320X2801/IMG_4121.jpeg ');
    background-size: cover;
    background-repeat: no-repeat;
    background-position: center;
    border: none !important;
    border-radius: 15px 15px 0 0 !important;
    box-shadow: none !important;
    max-height: calc(100dvh - var(--topBarBlockSize)) !important;
    top: -8.3px !important;
}

/* 调整对话框基础尺寸 */
.mes {
    --bubble-width: 93%;
    --vertical-spacing: 5rem;

    width: var(--bubble-width) !important;
    min-height: var(--bubble-min-height);
    margin: var(--vertical-spacing) auto !important;
    padding: 2rem 1rem !important;
}

/* 框长度 */
.mes_text {
    padding: 1px 1px 35px 1px !important; /* 上 右 下 左 */
}

/* 确保文本层级 */
.mes_block {
    position: relative;
    z-index: 999 !important;
    isolation: isolate;
}

/* ============================================== */
/* ★ 整体淡透毛玻璃 · 长气泡稳定不崩 · 不影响其他元素 */
/* ============================================== */
body.bubblechat .mes,
body.bubblechat .mes[is_user="true"],
.mes {
    max-width: 420px !important;
/*自定义宽度 按需适配*/

    /* 灰白毛玻璃 */
    background: rgba(255, 255, 255, 0.15) !important;
    backdrop-filter: blur(12px) saturate(100%) !important;
    -webkit-backdrop-filter: blur(12px) saturate(100%) !important;

    border-radius: 24px !important;
    box-shadow: 0 2px 12px rgba(100, 116, 139, 0.08) !important;
    border: 1px solid rgba(220, 220, 220, 0.25) !important;

    padding: 20px !important;
    padding-top: 240px !important;
    padding-bottom: 40px !important;
    margin: 40px auto 25px auto !important;

    position: relative;
    background-image: none !important;
    box-sizing: border-box !important;
    overflow: visible !important;

    will-change: backdrop-filter !important;
}

.mes_block {
    position: relative;
    z-index: 2;
}

/* ai文本 */
.mes[is_user="false"] .mes_text {
    padding: 35px 10px 10px 1px !important;
    letter-spacing: -0.5px;
}

/* 用户文本 */
.mes[is_user="true"] .mes_text {
    padding: 35px 10px 10px 1px !important;
    letter-spacing: -0.5px;
}

.mes_text {
    line-height: 2.1;
}
.swipes-counter {
  position: absolute;
  top: -30px;
  right: 10px;
  z-index: 999;
  pointer-events: none;
}
.swipes-counter {
  font-size: 10.5px;
  opacity: 1 !important;
  color: #666 !important;
  white-space: nowrap !important;
}
/*滑块图标 */
input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
    appearance: none;
    width: 25px;
    height: 25px;
    background: transparent url('https://img.51shazhu.com/autoupload/Se-4Rw5dFaWDOM3CV9c4D9iO_OyvX7mIgxFBfDMDErs/20260419/1Iu0/1328X1328/%E6%97%A0%E6%A0%87%E9%A2%98169_20260419203523.png') center/cover no-repeat;
    border: none;
    border-radius: 0;
    box-shadow: none;
    cursor: ew-resize;
    position: relative;
    z-index: 1;
}

input[type="range"] {
    background: rgba(255, 255, 255, 0.2) !important;
    backdrop-filter: blur(4px) !important;
    -webkit-backdrop-filter: blur(4px) !important;
    box-shadow: 0 0 0 rgba(180, 180, 180, 0.3) !important;
    border: 1px solid rgba(220, 220, 220, 0.5) !important;
    padding: 2px 8px !important;
    height: 6px !important;
    width: 100% !important;
    box-sizing: border-box !important;
}

input:not([type="file" i], [type="image" i], [type="checkbox" i], [type="radio" i]) {
  background-color: rgba(255,255,255,0.4) !important;
  box-shadow: 2px 2px 0px rgba(200, 200, 200, 0.6);
  border-radius: 0px;
  padding: 2px 1px;
  border: 1.5px solid #666;
  color: #333 !important;
  outline: none;
}

/*拓展键 */
.fa-bars {
  background: url(' https://img.51shazhu.com/autoupload/Se-4Rw5dFaWDOM3CV9c4D9iO_OyvX7mIgxFBfDMDErs/20260421/wHEA/1328X1328/%E6%97%A0%E6%A0%87%E9%A2%98169_20260419210711.png') center/contain no-repeat !important;
  width: 25px !important;
  height: 25px !important;
  margin-top: 7px !important;
margin-right: 10px !important;
  opacity: 1 !important
}

/*菜单键 */
#extensionsMenuButton {
  background: url(' https://img.51shazhu.com/autoupload/Se-4Rw5dFaWDOM3CV9c4D9iO_OyvX7mIgxFBfDMDErs/20260421/wt4I/1328X1328/%E6%97%A0%E6%A0%87%E9%A2%98169_20260419203745.png') center/contain no-repeat !important;
  width: 25px !important;
  height: 25px !important;
  margin-top: 7px !important;
opacity: 1 !important
}

/* 发送键 */
.fa-paper-plane {
  background: url(' https://img.51shazhu.com/autoupload/Se-4Rw5dFaWDOM3CV9c4D9iO_OyvX7mIgxFBfDMDErs/20260422/JwbD/1328X1328/%E6%97%A0%E6%A0%87%E9%A2%98169_20260419215704.png') center/contain no-repeat !important;
  width: 26px !important;
  height: 26px !important;
  margin-top: 7px !important;
  opacity: 1 !important
}

/* 暂停键 */
.fa-circle-stop::before {
  color: #666 !important;
  font-size: 1em;
  opacity: 1 !important;
}

/* 快捷回复按钮自定义 - QR图标替换 固定不移位 */
#quick-reply-rocket-button {
  font-size: 0 !important;
  width: 28px !important;
  height: 28px !important;
  opacity: 1 !important;
  background-image: url(' https://img.51shazhu.com/autoupload/Se-4Rw5dFaWDOM3CV9c4D9iO_OyvX7mIgxFBfDMDErs/20260422/NOky/1328X1328/%E6%97%A0%E6%A0%87%E9%A2%98169_20260419203523.png');
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  /* 固定基准，防止乱跑 */
  position: relative !important;
  top: 0 !important;
  left: 0 !important;
  margin: 0 !important;
  /* 保留你原本微调位置 */
  transform: translate(-7px, 6px) !important;
}

/* 头像位置 */
.mesAvatarWrapper {
    position: absolute !important;
    top: 50px !important;
    left: 16% !important;
    transform: translateX(-50%) !important;
    z-index: 2 !important;
    margin: 0 !important;
}
/* 头像大小 */
.mesAvatarWrapper .avatar {
  width: 100px !important;
  height: 100px !important;
  border-radius: 50% !important;
}

/* 用户头像框 */
.mes[is_user="true"] .mesAvatarWrapper::before {
  content: "";
  position: absolute;
  background-image: url(' https://img.51shazhu.com/autoupload/Se-4Rw5dFaWDOM3CV9c4D9iO_OyvX7mIgxFBfDMDErs/20260419/vf8D/1440X1440/%E6%97%A0%E6%A0%87%E9%A2%98194_20260419205055.png');
  background-size: cover;
  background-repeat: no-repeat;
  background-position: center;
  width: 152px;
  height: 152px;
  top: -40px;
  left: 49%;
  transform: translateX(-50%);
  z-index: 3;
  pointer-events: none;
}

/* AI头像框 */
.mes[is_user="false"] .mesAvatarWrapper::before {
  content: "";
  position: absolute;
  background-image: url( 'https://img.51shazhu.com/autoupload/Se-4Rw5dFaWDOM3CV9c4D9iO_OyvX7mIgxFBfDMDErs/20260419/PnWg/1440X1440/%E6%97%A0%E6%A0%87%E9%A2%98194_20260418005028.png');
  background-size: cover;
  background-repeat: no-repeat;
  background-position: center;
  width: 152px;
  height: 152px;
  top: -40px;
  left: 49%;
  transform: translateX(-50%);
  z-index: 3;
  pointer-events: none;
}

.mesAvatarWrapper .avatar img {
  width: 100% !important;
  height: 100% !important;
  border-radius: 50% !important;
  object-fit: cover !important;
  display: block !important;
}

.mesAvatarWrapper .avatar,
.mesAvatarWrapper .avatar img,
.mesAvatarWrapper .avatar::before,
.mesAvatarWrapper .avatar::after {
  box-shadow: none !important;
  filter: none !important;
  text-shadow: none !important; /* 移除文字阴影*/
}


/* 时间戳 */
.timestamp {
    position: absolute !important;
    top: 37px !important;
    right: 10px !important;
    color: #888 !important;
    font-size: 9.8px !important;
    z-index: 999 !important;
}

.timestamp::before {
    content: "" !important;
    margin-right: 0px;
  color: #888;
  display: inline !important; /* 改为inline使其与名字在同一行 */
  vertical-align: middle;
  position: relative;
  top: -1px;
}

.mes_block {
    position: relative;
    z-index: 999 !important;
    isolation: isolate;
}

/* 名字整体容器（只负责定位，不负责倾斜） */
.mes_block .ch_name {
  position: absolute !important;
  top: -157px !important;
  left: 110px !important;
  max-width: calc(100% - 105px) !important;
  z-index: 99999999 !important;
  letter-spacing: 0px !important;
  white-space: nowrap !important;
  background: transparent !important;
}

/* 名字+Name: 用单独容器包裹，倾斜只作用在这里 */
.mes_block .ch_name span {
  display: inline-block !important;
  color: #666 !important;
  font-size: 1em !important;
  font-weight: 700 !important;
  transform: skewX(-7deg) !important; /* 倾斜角度在这里调 */
}

/* Name: 前缀 */
.mes_block .ch_name::before {
  content: "Name: ";
  display: inline-block !important;
  color: #666 !important;
  font-weight: 700 !important;
  margin-right: 4px !important;
  transform: skewX(-7deg) !important; /* 和上面同一个角度 */
}

/* 自定义个签也用单独容器，和上面同角度 */
.mes_block .ch_name::after {
  content: "By your side";
  position: absolute !important;
  top: 20px !important;
  left: 0 !important;
  display: inline-block !important;
  color: #888 !important;
  font-size: 12px !important;
  font-weight: 700 !important;
  letter-spacing: 1px !important;
  white-space: nowrap !important;
  transform: skewX(-7deg) !important; /* 和上面同一个角度 */
}

.mes_block {
  position: relative !important;
  z-index: 99999 !important;
  overflow: visible !important;
}

.mes {
  overflow: visible !important;
}

/* 统一控制三个模块：固定三栏布局，高度锁定 */
.mesIDDisplay,
.mes .mes_timer,
.mes .tokenCounterDisplay {
    position: absolute !important;
    top: 150px !important; /* 统一控制上下位置，改这一个就全动 */
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    justify-content: flex-end !important;
    height: 40px !important; /* 强制固定高度，解决无数字时塌陷问题 */
    width: 100px !important; /* 固定宽度，防止左右偏移 */
    text-align: center !important;
    font-size: 0.9em !important;
    font-weight: 300 !important;
    color: #666 !important;
    white-space: nowrap !important;
}

/* 统一控制下方英文标签：固定在底部，永远对齐 */
.mesIDDisplay::after,
.mes .mes_timer::after,
.mes .tokenCounterDisplay::after {
    display: block !important;
    font-size: 11px !important;
    font-weight: 700 !important;
    color: #888 !important;
    letter-spacing: 1px !important;
    text-align: center !important;
    margin-top: auto !important; /* 强制贴在底部，永远不会上移 */
    position: relative !important;
    /* 这里是关键：给每个标签单独设置偏移 */
}

/* 各自的水平位置，复刻你图里的布局 */
.mesIDDisplay {
    left: -3px !important;
}
.mesIDDisplay::after {
    content: "Followings";
    left: 3px !important; /* 单独调这个标签的左右位置，正数值右移，负数值左移 */
}

.mes .mes_timer {
    left: 140px !important;
}
.mes .mes_timer::after {
    content: "Posts";
    left: 0px !important; /* 单独调这个标签的左右位置 */
}

.mes .tokenCounterDisplay {
    left: 285px !important;
}
.mes .tokenCounterDisplay::after {
    content: "Followers";
    left: 0px !important; /* 单独调这个标签的左右位置 */
}

/* ==编辑按钮 == */
.mes[is_user="false"],
.mes[is_user="true"] {
    position: relative !important;
    overflow: visible !important;
}

.mes[is_user="false"] .mes_buttons {
    position: absolute !important;
    top: 162px !important;
    right: -168px !important;
    z-index: 9999 !important;
    flex-direction: row !important;
    transform: none !important;
}

.mes[is_user="true"] .mes_buttons {
    position: absolute !important;
    top: 162px !important;
    right: -170px !important;
    z-index: 9999 !important;
    flex-direction: row !important;
    transform: none !important;
}

/* 编辑状态时按钮位置*/
.mes_edit_buttons {
    position: relative !important;
    top: 120px !important;
    left: -50px !important;
    margin-bottom: -20px !important;
    z-index: 100 !important;
}

/* --- 编辑的省略号图标 --- */
.fa-ellipsis-h,
.fa-ellipsis {
    background: url(' https://img.51shazhu.com/autoupload/Se-4Rw5dFaWDOM3CV9c4D9iO_OyvX7mIgxFBfDMDErs/20260419/hNwy/1328X1328/%E6%97%A0%E6%A0%87%E9%A2%98169_20260419212219.png') center/contain no-repeat !important;
    width: 22px !important;
    height: 22px !important;
    color: transparent !important;
z-index: 999 !important;
    opacity: 1 !important
}

/* --- 替换编辑图标 --- */
.fa-pencil-alt,
.fa-pencil {
    background: url('https://img.51shazhu.com/autoupload/Se-4Rw5dFaWDOM3CV9c4D9iO_OyvX7mIgxFBfDMDErs/20260419/gvNj/1328X1328/%E6%97%A0%E6%A0%87%E9%A2%98169_20260419213252.png ') center/contain no-repeat !important;
    width: 22px !important;
    height: 22px !important;
    color: transparent !important;
z-index: 999 !important;
    opacity: 1 !important
}

/* 导航栏完全无背景、透明 */
#top-bar::after {
    display: none !important;
}

#top-bar::before {
    display: none !important;
}

#top-settings-holder .drawer {
    flex: 1;
}

#top-settings-holder .drawer-icon {
    transform: scale(0.55) !important;
    background: linear-gradient(45deg, #666, #666) !important;
    -webkit-background-clip: text !important;
    background-clip: text !important;
    color: transparent !important;
    opacity: 0.7 !important;
}

/* 底栏源@nakari老师的悬浮底栏结构  */
#sheld, 
#chat {
    height: calc(102dvh + var(--bottomFormBlockSize));
    max-height: calc(102dvh + var(--bottomFormBlockSize));
}

/* 底栏自定义宽度毛玻璃版 */
#send_form, body.no-blur #send_form {
  /* 核心毛玻璃 */
  background-color: rgba(255, 255, 255, 0.25) !important;
  backdrop-filter: blur(20px) !important;
  -webkit-backdrop-filter: blur(20px) !important;

  /* 自定义宽度 */
  width: 700px !important;
  max-width: 90% !important;
  margin: 0 auto !important;

  /* 外观 */
  border-radius: 25px !important;
  border: 1px solid rgba(255, 255, 255, 0.3) !important;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.1) !important;
  padding: 3px 5px !important;
  transition: all 0.3s ease !important;

  /* 布局保持悬浮结构 */
  position: relative !important;
  display: flex !important;
  align-items: center !important;

  /* 无背景图 */
  background-image: none !important;
  background: transparent !important;
  outline: none !important;
}


/* 去掉内部小白条 */
#send_form::after {
  display: none !important;
}

/* 底栏悬停效果 */
#send_form:hover, body.no-blur #send_form:hover {
  transform: translateY(-3px);
  background-color: rgba(255, 255, 255, 0.55) !important;
  box-shadow: none !important;
}

/* 输入框 */
#send_textarea {
  resize: none;
  position: relative;
  z-index: 3;
  background: transparent !important;
  border: none !important;
  outline: none !important;
  width: 100% !important;
  min-height: 40px !important;
  padding: 8px 12px !important;
  color: #333 !important;
  font-size: 14px !important;
  clip-path: none !important;
}

textarea {
  background: transparent !important;
  border: none !important;
  outline: none !important;
}

/* 图标间距 */
#rightSendForm, #leftSendForm {
  gap: 3px;
}

/* 悬浮定位 */
#form_sheld {
    position: sticky;
    bottom: 105px;
    transition: transform 0.3s ease;
}

#send_form {
  margin-bottom: 15px;
}

/* 预设 */
/* 背景 */
#completion_prompt_manager #completion_prompt_manager_list {
  background-color: rgba(255, 255, 255, 0.2) !important;
  border-radius: 0px !important;
  box-shadow: 0 0px 0px rgba(200,200,200,0.3) !important;
  padding: 12px !important;
  transition: all 0.3s ease !important;
  border: 0px solid rgba(200,200,200,0.2) !important;
  position: relative !important;
  overflow: hidden !important;
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name, #completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
    color: #666;
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt_disabled {
  opacity: 1;
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
  background-color: rgba(255,255,255,0.4) !important;
  color: #444 !important;
  box-shadow: 0px 0px 0px rgba(200,200,200,0.3) !important;
  border: 1.5px solid #ddd;
outline: 1.5px solid #666 !important;
  border-radius: 0px !important;
  padding: 1px 1px !important;
  margin: 5px 5px !important;
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled {
  background-color: rgba(255,255,255,0.3) !important;
  color: #444 !important;
  box-shadow: 0px 2px 4px rgba(200,200,200,0.3) !important;
  border: 1.5px solid #ddd;
outline: 1.5px solid #666 !important;
  border-radius: 0px !important;
  margin: 8px 5px !important;
  opacity: 1 !important;
}

/* 条目已开启颜色 代码源@hy */
.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .fa-toggle-on {
    color: #333 !important;
    text-shadow: 0 0 0px #000 !important;
opacity: 1 !important;
}

/*菜单按钮*/
.menu_button {
  background-color: rgba(255,255,255,0.4)!important;
  box-shadow: 2px 2px 0px rgba(200,200,200,0.6);
  border: 1.5px solid #666 !important;
  border-radius: 1px !important;
  padding: 1px 4px !important;
  color: #444 !important;
  opacity: 1 !important
}

/* 代码块 */
code, .hljs {
  position: relative;
  background-color: rgba(255,255,255,0.4) !important;
  border-radius: 1px !important;
  border: 1.5px solid #666;
  box-shadow: 2px 2px 0px rgba(200,200,200,0.6);
   color: #444;
}

/* 下拉框 */
select {
    background-size: 100%;
  background: rgba(255,255,255,0.4);
  color: #666 !important;
  border: 1.5px solid #666 !important;
  background-position: center;
  box-shadow:
    inset 0 0 0 0px #fff,
    0 0px 0px rgba(100,100,100,0.5),
    inset 0 0 1px rgba(240,240,240,1) !important;
  border-radius: 1px;
  transition: all 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
  padding: 2px 4px !important;
  color: #444;
  background-position: center;
  position: relative;
}

select,
select option {
  color: #444 !important;
}

/* ========== 自定义勾选框 框架来源@千尾老师 ========== */
/* 1. 基础框架 */
input[type="checkbox"] {
  appearance: none;
  -webkit-appearance: none;
  position: relative;
  width: 19px; /* 图片宽度 */
  height: 19px; /* 图片高度 */

  /* 用背景图代替边框 */
  border: none !important;
  outline: none !important;
  background-color: transparent !important;

  /* 背景图通用设置 */
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;

  transition: all 0.2s ease-in-out;
  box-shadow: none !important;
  margin: 0 3px 0 0;
  transform: translateY(4px); /* Y轴微调 */
  cursor: pointer;
}

